WITH fixes(slug,pos,why) AS (VALUES ('legislacao-contravencoes-revisao',1,'Correto. O art. 4º da Lei das Contravenções Penais estabelece que a tentativa de contravenção não é punível, diferentemente da regra geral sobre tentativa de crime.'),
('legislacao-contravencoes-revisao',5,'Correto. O art. 5º da Lei das Contravenções Penais prevê prisão simples e multa como penas principais aplicáveis às contravenções.'),
('legislacao-ambientais-revisao',4,'Correto. O art. 21 da Lei 9.605/1998 prevê multa entre as sanções penais aplicáveis à pessoa jurídica, além de restritivas de direitos e prestação de serviços à comunidade.'),
('legislacao-armas-revisao',5,'Correto. O art. 1º da Lei 10.826/2003 institui o Sistema Nacional de Armas, Sinarm, no âmbito da Polícia Federal.'),
('legislacao-armas-revisao',7,'Correto. O art. 3º da Lei 10.826/2003 exige o registro de arma de fogo no órgão competente, conforme as regras legais.'),
('legislacao-interceptacao-revisao',4,'Correto. O art. 1º da Lei 9.296/1996 condiciona a interceptação de comunicações telefônicas à ordem do juiz competente, observadas as hipóteses legais.'),
('legislacao-juizados-revisao',6,'Correto. Pelo art. 74 da Lei 9.099/1995, a composição dos danos civis homologada por sentença irrecorrível vale como título executivo no juízo civil competente.'),
('legislacao-lep-revisao',1,'Errado. O art. 11 da Lei de Execução Penal inclui expressamente a assistência educacional e a religiosa entre as modalidades de assistência.'),
('legislacao-lep-revisao',2,'Correto. O art. 1º da Lei de Execução Penal prevê efetivar a sentença ou decisão criminal e proporcionar condições para a harmônica integração social do condenado e internado.'),
('legislacao-lep-revisao',4,'Correto. O art. 3º da Lei de Execução Penal assegura ao condenado e ao internado todos os direitos não atingidos pela sentença ou pela lei.'),
('legislacao-organizacoes-revisao',4,'Errado. O art. 1º, § 1º, da Lei 12.850/2013 exige associação de quatro ou mais pessoas para configurar organização criminosa, além dos demais requisitos legais.'),
('legislacao-abuso-revisao',1,'Correto. O art. 3º da Lei 13.869/2019 prevê ação penal pública incondicionada para os crimes de abuso de autoridade.'),
('legislacao-delegado-revisao',5,'Correto. O art. 2º, § 6º, da Lei 12.830/2013 exige que o indiciamento, ato privativo do delegado de polícia, seja fundamentado mediante análise técnico-jurídica.'),
('legislacao-delegado-revisao',8,'Correto. O art. 2º, § 5º, da Lei 12.830/2013 estabelece que a remoção do delegado de polícia deve ocorrer por ato fundamentado.'),
('legislacao-temporaria-revisao',5,'Correto. O art. 2º da Lei 7.960/1989 prevê que a prisão temporária seja decretada pelo juiz mediante representação da autoridade policial ou requerimento do Ministério Público.'),
('legislacao-terrorismo-revisao',7,'Correto. O art. 5º da Lei 13.260/2016 prevê punição de atos preparatórios de terrorismo quando demonstrado propósito inequívoco de consumar o delito.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL AND length(trim(coalesce(e.value->>'why','')))<25 THEN jsonb_set(e.value,'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.slug=sm.slug AND f.pos=e.ordinality WHERE sm.slug IN (SELECT DISTINCT slug FROM fixes) GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;